/* solver_qpsol:(h[656x656,596nz],g[656],a[1128x656,3605nz],lba[1128],uba[1128],lbx[656],ubx[656],x0[656],lam_x0[656],lam_a0[1128],q[0x656],p[])->(x[656],cost,lam_a[1128],lam_x[656]) */
static int casadi_f3(const casadi_real** arg, casadi_real** res, casadi_int* iw, casadi_real* w, int mem) {
  OSQPWorkspace *work=casadi_f3_mem[mem];
  casadi_int i, n, offset;
  /* Set objective */
  if (arg[1]) {
    casadi_copy(arg[1], 656, w);
  } else {
    casadi_clear(w, 656);
  }
  if (osqp_update_lin_cost(work, w)) return 1;
  /* Set bounds */
  if (arg[5]) {
    casadi_copy(arg[5], 656, w);
  } else {
    casadi_fill(w, 656, -casadi_inf);
  }
  if (arg[3]) {
    casadi_copy(arg[3], 1128, w+656);
  } else {
    casadi_fill(w+656, 1128, -casadi_inf);
  }
  if (arg[6]) {
    casadi_copy(arg[6], 656, w+1784);
  } else {
    casadi_fill(w+1784, 656, casadi_inf);
  }
  if (arg[4]) {
    casadi_copy(arg[4], 1128, w+2440);
  } else {
    casadi_fill(w+2440, 1128, casadi_inf);
  }
  if (osqp_update_bounds(work, w, w+1784)) return 1;
  /* Project Hessian */
  casadi_tri_project(arg[0], casadi_s0, w, 0);/* Get constraint matrix */
  offset = 0;
  for (i=0; i< 656; ++i) {
    w[596+offset] = 1;
    offset++;
    n = casadi_s1[i+1]-casadi_s1[i];
    casadi_copy(arg[2]+casadi_s1[i], n, w+offset+596);
    offset+= n;
  }
  /* Pass Hessian and constraint matrices */
  if (osqp_update_P_A(work, w, 0, 596, w+596, 0, 4261)) return 1;
  if (osqp_warm_start_x(work, arg[7])) return 1;
  if (arg[8]) {
    casadi_copy(arg[8], 656, w);
  } else {
    casadi_clear(w, 656);
  }
  if (arg[9]) {
    casadi_copy(arg[9], 1128, w+656);
  } else {
    casadi_clear(w+656, 1128);
  }
  if (osqp_warm_start_y(work, w)) return 1;
  if (osqp_solve(work)) return 1;
  if (res[1]) casadi_copy(&work->info->obj_val, 1, res[1]);
  if (res[0]) casadi_copy(work->solution->x, 656, res[0]);
  if (res[3]) casadi_copy(work->solution->y, 656, res[3]);
  if (res[2]) casadi_copy(work->solution->y+656, 1128, res[2]);
  if (work->info->status_val != OSQP_SOLVED) {
    return -1000;
  }
  return 0;
  return 0;
}

